    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    // DropSeen: remove every item whose id is already present in the 'seen'
    // store. Only state-read is granted, so this node can look up keys but
    // cannot write them; marking items seen is done by a downstream node.
    // No enrichment fetch is performed: the node's `with` clause grants no
    // HTTP capability, and this node's output depends only on the seen store.
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
